// Fuentes del informe de desempeño (extraídas del PDF SISNOTAS de referencia).
// Se incrustan en jsPDF para que el boletín use EXACTAMENTE la misma tipografía:
//  - HelveticaCond  normal  → Helvetica-Condensed  (texto: logros, escala)
//  - HelveticaCond  bold    → Helvetica-CondensedBlack (títulos, áreas, cabeceras)
//  - ArialNarrow    normal  → Arial Narrow (números y valores)
/* eslint-disable */
const HELV_COND = "";
const HELV_COND_BLACK = "";
const ARIAL_NARROW = "";

export function registerBoletinFonts(pdf: any) {
  pdf.addFileToVFS("HelveticaCondensed.ttf", HELV_COND);
  pdf.addFont("HelveticaCondensed.ttf", "HelveticaCond", "normal");
  pdf.addFileToVFS("HelveticaCondensedBlack.ttf", HELV_COND_BLACK);
  pdf.addFont("HelveticaCondensedBlack.ttf", "HelveticaCond", "bold");
  pdf.addFileToVFS("ArialNarrow.ttf", ARIAL_NARROW);
  pdf.addFont("ArialNarrow.ttf", "ArialNarrow", "normal");
}
